// The Cloudflare Worker: the built Next.js app, plus the daily scheduled run
// that sends weekly reminder emails (see "triggers" in wrangler.jsonc).
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { sendReminders, type ReminderEnv } from "./worker/reminders";

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: ReminderEnv) {
    console.log("weekly reminders", JSON.stringify(await sendReminders(env)));
  },
};
